question.solution:
def first_unique_char(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for index, ch in enumerate(s):
        if counts[ch] == 1:
            return index
    return -1

print(first_unique_char('leetcode'))
print(first_unique_char('aabb'))
print(first_unique_char(''))
